import { z } from 'zod';

import { LIMITS } from '../constants';
import { isoDateTime, userSummary } from './common';

export const chatMessage = z.object({
  /** Generated by the sender's app, so a retried send never duplicates. */
  id: z.uuid(),
  /** The chat it's in: an activity's or a community's (the other is null). */
  activityId: z.uuid().nullable(),
  communityId: z.uuid().nullable(),
  kind: z.enum(['user', 'system']),
  /** Null for system lines such as "Kavindu joined". */
  sender: userSummary.nullable(),
  body: z.string(),
  createdAt: isoDateTime,
});
export type ChatMessage = z.infer<typeof chatMessage>;

export const messagesQuery = z.object({
  /** Return messages after this one (catch-up after reconnecting). */
  after: z.uuid().optional(),
  limit: z.coerce.number().int().min(1).max(200).default(100),
});

export const messagesPage = z.object({
  /** Oldest first. */
  messages: z.array(chatMessage),
  /** Latest point any other member has read to; drives "Seen". */
  othersReadUpTo: isoDateTime.nullable(),
});
export type MessagesPage = z.infer<typeof messagesPage>;

export const sendMessageInput = z.object({
  id: z.uuid(),
  body: z.string().trim().min(1).max(LIMITS.messageMax),
});
export type SendMessageInput = z.infer<typeof sendMessageInput>;

export const markReadInput = z.object({
  /** The newest message the user has seen. */
  messageId: z.uuid(),
});

/** Events the server pushes over the chat WebSocket. */
export const serverEvent = z.discriminatedUnion('type', [
  z.object({ type: z.literal('message'), message: chatMessage }),
  z.object({ type: z.literal('typing'), user: userSummary }),
  z.object({ type: z.literal('read'), userId: z.string(), upTo: isoDateTime }),
  /** A moderator removed this message. */
  z.object({ type: z.literal('removed'), messageId: z.string() }),
]);
export type ServerEvent = z.infer<typeof serverEvent>;

/** Events the app may send over the chat WebSocket. */
export const clientEvent = z.discriminatedUnion('type', [z.object({ type: z.literal('typing') })]);
export type ClientEvent = z.infer<typeof clientEvent>;

export const registerPushTokenInput = z.object({
  /** Expo push token, e.g. "ExponentPushToken[xxxx]". */
  token: z.string().regex(/^Expo(nent)?PushToken\[.+\]$/),
});

/** A row on the Chats screen: one of your group chats, with what's new in it. */
export const chatPreview = z.object({
  kind: z.enum(['activity', 'community']),
  /** The activity's or community's id. */
  id: z.uuid(),
  title: z.string(),
  /** The activity's cover or the community's logo. */
  imageUrl: z.url().nullable(),
  /** When the activity starts (null for communities). */
  startsAt: isoDateTime.nullable(),
  cancelled: z.boolean(),
  /** You turned its notifications off. */
  muted: z.boolean(),
  lastMessage: z
    .object({
      kind: z.enum(['user', 'system']),
      /** Null for system lines and deleted accounts. */
      senderName: z.string().nullable(),
      body: z.string(),
      mine: z.boolean(),
      createdAt: isoDateTime,
    })
    .nullable(),
  /** Messages from others since you last read it. */
  unread: z.number().int(),
});
export type ChatPreview = z.infer<typeof chatPreview>;
